import os
import time
import requests
import json
import uuid
from datetime import datetime
import logging
from typing import Dict, Any

logging.basicConfig(
    filename='health.log',
    level=logging.INFO,
    format='%(message)s'
)

def generate_request_id() -> str:
    return uuid.uuid4().hex[:32].lower()

def log_health_event(event: Dict[str, Any]) -> None:
    logging.info(json.dumps(event))

def poll_health_endpoint() -> None:
    url = os.getenv('HEALTH_URL')
    if not url:
        raise ValueError("HEALTH_URL environment variable not set")

    while True:
        try:
            response = requests.get(url)
            response.raise_for_status()
            data = response.json()

            if not isinstance(data, dict) or 'service' not in data or 'status' not in data:
                raise ValueError("Invalid JSON response format")

            event = {
                'timestamp': datetime.utcnow().isoformat(timespec='milliseconds') + 'Z',
                'service': data['service'],
                'status': data['status'],
                'request_id': generate_request_id()
            }
            log_health_event(event)

        except requests.exceptions.RequestException as e:
            event = {
                'timestamp': datetime.utcnow().isoformat(timespec='milliseconds') + 'Z',
                'error': str(e)
            }
            log_health_event(event)
        except ValueError as e:
            event = {
                'timestamp': datetime.utcnow().isoformat(timespec='milliseconds') + 'Z',
                'error': str(e)
            }
            log_health_event(event)

        time.sleep(10)

if __name__ == "__main__":
    poll_health_endpoint()
